2	import { isMinorUnits, isSupportedCurrency, money, multiply, sum } from "./money.js";
3	
4	export const CHANNELS = ["web", "store", "marketplace"] as const;
5	export type Channel = (typeof CHANNELS)[number];
6	
7	export type OrderStatus = "placed" | "cancelled";
8	
9	export interface OrderLine {
10	  readonly sku: string;
11	  readonly name: string;
12	  readonly qty: number;
13	  readonly unitPriceCents: number;
14	}
15	
16	export interface Order {
17	  readonly id: string;
18	  readonly customerId: string;
19	  /** Legacy: kept on the order for receipts until the customer profile lookup exists. */
20	  readonly customerEmail: string;
21	  readonly lines: readonly OrderLine[];
22	  readonly status: OrderStatus;
23	  readonly channel: Channel;
24	  readonly currency: string;
25	  /** ISO-8601 instant. */
26	  readonly placedAt: string;
27	  /** ISO-8601 instant, set when the order is cancelled. */
28	  readonly cancelledAt?: string;
29	}
30	
31	/** What a caller supplies to place an order; identity and timestamps come from the service. */
32	export interface NewOrder {
33	  readonly customerId: string;
34	  readonly customerEmail: string;
35	  readonly channel: Channel;
36	  readonly currency: string;
37	  readonly lines: readonly OrderLine[];
38	}
39	
40	export const LIMITS = {
41	  maxLines: 100,
42	  maxQtyPerLine: 1000,
43	  maxSkuLength: 64,
44	  maxNameLength: 200,
45	  maxIdLength: 100,
46	  maxEmailLength: 254,
47	  /** Upper bound of an order total in minor units; protects against absurd inputs. */
48	  maxTotalMinor: 100_000_000,
49	} as const;
50	
51	const SKU_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
52	const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
53	
54	/**
55	 * Builds a placed order after checking every invariant:
56	 * at least one line, positive integer quantities, prices as integer minor units,
57	 * a supported currency and a bounded total. All problems are reported together.
58	 */
59	export function createOrder(input: NewOrder, meta: { id: string; placedAt: string }): Order {
60	  const issues = collectIssues(input);
61	  if (issues.length > 0) {
62	    throw new ValidationError(issues);
63	  }
64	  return {
65	    id: meta.id,
66	    customerId: input.customerId,
67	    customerEmail: input.customerEmail,
68	    lines: input.lines.map((line) => ({
69	      sku: line.sku,
70	      name: line.name,
71	      qty: line.qty,
72	      unitPriceCents: line.unitPriceCents,
73	    })),
74	    status: "placed",
75	    channel: input.channel,
76	    currency: input.currency,
77	    placedAt: meta.placedAt,
78	  };
79	}
80	
81	/** Orders can be cancelled this long after they were placed. */
82	export const CANCELLATION_WINDOW_DAYS = 30;
83	
84	const DAY_MS = 24 * 60 * 60 * 1000;
85	
86	export function canCancel(order: Order, at: string): boolean {
87	  if (order.status !== "placed") {
88	    return false;
89	  }
90	  const elapsed = Date.parse(at) - Date.parse(order.placedAt);
91	  return elapsed <= CANCELLATION_WINDOW_DAYS * DAY_MS;
92	}
93	
94	export function cancel(order: Order, cancelledAt: string): Order {
95	  if (!canCancel(order, cancelledAt)) {
96	    const reason = order.status === "placed" ? "cancelled after the cancellation window" : "cancelled";
97	    throw new InvalidStateError(order.id, order.status, reason);
98	  }
99	  return { ...order, status: "cancelled", cancelledAt };
100	}
101	
102	/** Order total in minor units: the sum of qty x unit price over all lines. */
103	export function totalCents(order: Pick<Order, "lines" | "currency">): number {
104	  const lineTotals = order.lines.map((line) => multiply(money(line.unitPriceCents, order.currency), line.qty));
105	  return sum(lineTotals, order.currency).amountMinor;
106	}
107	
108	function collectIssues(input: NewOrder): ValidationIssue[] {
109	  const issues: ValidationIssue[] = [];
110	  const fail = (path: string, message: string): void => {
111	    issues.push({ path, message });
112	  };
113	
114	  if (!isNonBlank(input.customerId) || input.customerId.length > LIMITS.maxIdLength) {
115	    fail("customerId", `must be 1-${LIMITS.maxIdLength} characters`);
116	  }
117	  if (
118	    typeof input.customerEmail !== "string" ||
119	    input.customerEmail.length > LIMITS.maxEmailLength ||
120	    !EMAIL_PATTERN.test(input.customerEmail)
121	  ) {
122	    fail("customerEmail", "must be a valid email address");
123	  }
124	  if (!(CHANNELS as readonly unknown[]).includes(input.channel)) {
125	    fail("channel", `must be one of ${CHANNELS.join(", ")}`);
126	  }
127	  if (!isSupportedCurrency(input.currency)) {
128	    fail("currency", "must be a supported ISO-4217 currency code");
129	  }
130	  if (!Array.isArray(input.lines) || input.lines.length === 0) {
131	    fail("lines", "must contain at least one line");
132	    return issues;
133	  }
134	  if (input.lines.length > LIMITS.maxLines) {
135	    fail("lines", `must contain at most ${LIMITS.maxLines} lines`);
136	  }
137	
138	  let runningTotal = 0;
139	  input.lines.forEach((line, index) => {
140	    const at = `lines[${index}]`;
141	    if (typeof line.sku !== "string" || line.sku.length > LIMITS.maxSkuLength || !SKU_PATTERN.test(line.sku)) {
142	      fail(`${at}.sku`, "must be an alphanumeric SKU of at most 64 characters");
143	    }
144	    if (!isNonBlank(line.name) || line.name.length > LIMITS.maxNameLength) {
145	      fail(`${at}.name`, `must be 1-${LIMITS.maxNameLength} characters`);
146	    }
147	    if (!Number.isInteger(line.qty) || line.qty < 1 || line.qty > LIMITS.maxQtyPerLine) {
148	      fail(`${at}.qty`, `must be an integer between 1 and ${LIMITS.maxQtyPerLine}`);
149	    }
150	    if (!isMinorUnits(line.unitPriceCents)) {
151	      fail(`${at}.unitPriceCents`, "must be a non-negative integer (minor units)");
152	      return;
153	    }
154	    if (Number.isInteger(line.qty) && line.qty > 0) {
155	      runningTotal += line.qty * line.unitPriceCents;
156	    }
157	  });
158	  if (runningTotal > LIMITS.maxTotalMinor) {
159	    fail("lines", `order total exceeds the maximum of ${LIMITS.maxTotalMinor} minor units`);
160	  }
161	  return issues;
162	}
